(4462351, 643128, 88704, '<td valign="top">The focus should really be on the eye and not the eyelashes.</td>', 'The focus should really be on the eye and not the eyelashes.', '2008-02-06 01:37:03.000000', NULL, 1),
(4462352, 642910, 84907, '<td valign="top">Wow, very nice pop in the eyes with the lighting.  The overall lighting looks uneven on the face and that is probably my biggest concern, but I think you did a very nice job of trying to light up those eyes.</td>', 'Wow, very nice pop in the eyes with the lighting.  The overall lighting looks uneven on the face and that is probably my biggest concern, but I think you did a very nice job of trying to light up those eyes.', '2008-02-06 01:37:57.000000', NULL, 1),
