(4468006, 643128, 63503, '<td valign="top">Interesting title !!</td>', 'Interesting title !!', '2008-02-07 10:39:57.000000', NULL, 1),
(4468007, 642597, 84656, '<td valign="top">That''s quite freaky.  The catchlight on the iris distracts and the eye itself appears a bit soft.</td>', 'That''s quite freaky.  The catchlight on the iris distracts and the eye itself appears a bit soft.', '2008-02-07 10:40:21.000000', NULL, 1),
(4468009, 643071, 84656, '<td valign="top">Amazing colour.  Catchlight is a bit hot though.</td>', 'Amazing colour.  Catchlight is a bit hot though.', '2008-02-07 10:41:15.000000', NULL, 1),
(4468015, 642733, 63503, '<td valign="top">Did you allow the red pupils purposely?</td>', 'Did you allow the red pupils purposely?', '2008-02-07 10:43:52.000000', NULL, 1),
(4468019, 641981, 84656, '<td valign="top">Those eye''s are nice and sharp.  Lost a bit of detail on the left side of her face as it''s a bit overexposed.  I''m undecided about the gauze? framing the eyes.  With such pretty eye''s I''m frustrated that I can not see the rest of her face... then again it does enforce the focal point, perhaps the texture just doesn''t appeal to me.<br/> <br/>Nice one and good luck.</td>', 'Those eye''s are nice and sharp.  Lost a bit of detail on the left side of her face as it''s a bit overexposed.  I''m undecided about the gauze? framing the eyes.  With such pretty eye''s I''m frustrated that I can not see the rest of her face... then again it does enforce the focal point, perhaps the texture just doesn''t appeal to me. Nice one and good luck.', '2008-02-07 10:47:03.000000', NULL, 1),
(4468023, 642443, 83375, '<td valign="top">I like the emotion in the eyes, the shot could have been executed better though.</td>', 'I like the emotion in the eyes, the shot could have been executed better though.', '2008-02-07 10:48:50.000000', NULL, 1),
(4468024, 642293, 79335, '<td valign="top">very nice and original! 8</td>', 'very nice and original! 8', '2008-02-07 10:49:16.000000', NULL, 1),
(4468025, 641824, 83375, '<td valign="top">Is that a wirehair? I''ve got one but she isn''t very scruffy at all..</td>', 'Is that a wirehair? I''ve got one but she isn''t very scruffy at all..', '2008-02-07 10:50:14.000000', NULL, 1),
