(4470982, 642492, 39679, '<td valign="top">Great control of DOF!  Having just the girl''s face in focus really adds to the interest of this shot.  Exposure and color are perfect and having a light colored background really helps further a sense of sweetness and innocence.  Great job.</td>', 'Great control of DOF!  Having just the girl''s face in focus really adds to the interest of this shot.  Exposure and color are perfect and having a light colored background really helps further a sense of sweetness and innocence.  Great job.', '2008-02-08 11:24:46.000000', NULL, 1),
(4470996, 643058, 76430, '<td valign="top">Excellent picture.  The eyes really grab my attention.  Nice lighting and focus.  Beautiful girl.</td>', 'Excellent picture.  The eyes really grab my attention.  Nice lighting and focus.  Beautiful girl.', '2008-02-08 11:33:57.000000', NULL, 1),
(4470998, 642872, 70100, '<td valign="top">No question who''s in a bad mood today.  Great shot.</td>', 'No question who''s in a bad mood today.  Great shot.', '2008-02-08 11:34:16.000000', NULL, 1),
