(4494278, 642849, 30982, '<td valign="top">This is great - the reflection in the eye is excellent, and I have one heckuva time getting either of my critters to hold still long enough to get such great focus.  Nicely done!</td>', 'This is great - the reflection in the eye is excellent, and I have one heckuva time getting either of my critters to hold still long enough to get such great focus.  Nicely done!', '2008-02-18 10:37:51.000000', NULL, 0),
(4494418, 641631, 5885, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by ShutterHack:</b></div><hr/><i> Love it Leroy! Did you take any of the eyes starring up at the couchie? </i></td></tr></table> <br/> <br/>No, I thought eye contact was the better approach.</td>', 'Originally posted by ShutterHack: Love it Leroy! Did you take any of the eyes starring up at the couchie?   No, I thought eye contact was the better approach.', '2008-02-18 12:04:06.000000', NULL, 0),
