INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4508996, 642716, 24454, '<td valign="top">I can''t figure out why this scored only 5.3.   I think its awesome and I love the other cat in the background that you can barely make out.    This is very cool!<br/> <br/></td>', 'I can''t figure out why this scored only 5.3.   I think its awesome and I love the other cat in the background that you can barely make out.    This is very cool! ', '2008-02-23 00:35:05.000000', NULL, 0),
(4509290, 642431, 68035, '<td valign="top">Roz<br/> <br/>Another stunning photograph, great colours but its the composition that really does it for me here, such magnificent symettry in terms of shapes, I swear that if it was not for the different coloured plummage I would have thought it was a reflection<br/> <br/>As ever a brilliant concept brilliantly delivered</td>', 'Roz Another stunning photograph, great colours but its the composition that really does it for me here, such magnificent symettry in terms of shapes, I swear that if it was not for the different coloured plummage I would have thought it was a reflection As ever a brilliant concept brilliantly delivered', '2008-02-23 04:56:28.000000', NULL, 0),
(4509329, 641154, 68035, '<td valign="top">Peter<br/> <br/>What a fantastic portrait of your son, captures everything that being a boy is all about.  Beautiful centred composition and great symettry.  As ever terrific sharpness, I think the definition of the eyebrows could almost be an image on its own<br/> <br/>Talk about a keeper!!!!!!</td>', 'Peter What a fantastic portrait of your son, captures everything that being a boy is all about.  Beautiful centred composition and great symettry.  As ever terrific sharpness, I think the definition of the eyebrows could almost be an image on its own Talk about a keeper!!!!!!', '2008-02-23 05:08:39.000000', NULL, 0),
(4509341, 642456, 68035, '<td valign="top">Deb<br/> <br/>What a wonderful image (and this from a non cat lover).  Tremendous high ket shot and the darkness of the eyelids (especially the one on the left) combined with the subtle eye colour and pupil just give a brilliant focal point and add real oopm to the image<br/> <br/>Top shot</td>', 'Deb What a wonderful image (and this from a non cat lover).  Tremendous high ket shot and the darkness of the eyelids (especially the one on the left) combined with the subtle eye colour and pupil just give a brilliant focal point and add real oopm to the image Top shot', '2008-02-23 05:12:04.000000', NULL, 0),
(4509358, 643061, 68035, '<td valign="top">How dare you take a picture in an eye challenge of a wonderfully sharp pair of eyes with great colour that are well framed....Jeez no wonder you only scored 4.85....<br/> <br/>DPC voting....Who the hell understands it?</td>', 'How dare you take a picture in an eye challenge of a wonderfully sharp pair of eyes with great colour that are well framed....Jeez no wonder you only scored 4.85.... DPC voting....Who the hell understands it?', '2008-02-23 05:26:29.000000', NULL, 0),
(4509790, 643017, 61651, '<td valign="top">I love your photographer''s comments, and you got that disdainful glare (with a hint of threat) captured very well.  I can sympathize - it''s hard not to respect such a strong sense of self.</td>', 'I love your photographer''s comments, and you got that disdainful glare (with a hint of threat) captured very well.  I can sympathize - it''s hard not to respect such a strong sense of self.', '2008-02-23 12:34:26.000000', NULL, 0),
(4509795, 642456, 61651, '<td valign="top">This high key is really lovely; and the framing is well chosen - I especially like the bit of black showing in the top corners - complements the whole image without being "too much" (I say that as if I know what "too much" means ;)  ).</td>', 'This high key is really lovely; and the framing is well chosen - I especially like the bit of black showing in the top corners - complements the whole image without being "too much" (I say that as if I know what "too much" means ;)  ).', '2008-02-23 12:37:53.000000', NULL, 0),
(4509803, 642848, 61651, '<td valign="top">Infinite patience in those eyes.  Happy birthday Coco!</td>', 'Infinite patience in those eyes.  Happy birthday Coco!', '2008-02-23 12:40:42.000000', NULL, 0),
(4509807, 642534, 61651, '<td valign="top">Why do people expect you to Hoover your cat before you take a picture?   The dusty bits make me think this cat is a bit of a scamp, and is always worming her way into impossible places.</td>', 'Why do people expect you to Hoover your cat before you take a picture?   The dusty bits make me think this cat is a bit of a scamp, and is always worming her way into impossible places.', '2008-02-23 12:44:33.000000', NULL, 0),
(4509815, 643059, 61651, '<td valign="top">I think you got the focus spot-on here.  Makes me want to bawl right along with him.  :)  And as for soft focus, did you ever try to focus your  eyes when you''re weeping?  Do things look pin-sharp then?  You have helped us see through his eyes.</td>', 'I think you got the focus spot-on here.  Makes me want to bawl right along with him.  :)  And as for soft focus, did you ever try to focus your  eyes when you''re weeping?  Do things look pin-sharp then?  You have helped us see through his eyes.', '2008-02-23 12:48:15.000000', NULL, 0),
(4510569, 642848, 62318, '<td valign="top">Happy belated, Coco. Wonderful expression. I hope my one dog lasts as long.</td>', 'Happy belated, Coco. Wonderful expression. I hope my one dog lasts as long.', '2008-02-23 18:29:22.000000', NULL, 0),
(4510594, 642456, 62318, '<td valign="top">Very nice high key. The eye detail is amazing. I love how your mind seems to fill in the details on the left hand side. Very nice soft and serene light, makes the kitty look heavenly.</td>', 'Very nice high key. The eye detail is amazing. I love how your mind seems to fill in the details on the left hand side. Very nice soft and serene light, makes the kitty look heavenly.', '2008-02-23 18:41:42.000000', NULL, 0),
(4511012, 643020, 62318, '<td valign="top">Eerily conveyed, yet still very intriguing. Very nice detail and a teriffic take on the challenge.</td>', 'Eerily conveyed, yet still very intriguing. Very nice detail and a teriffic take on the challenge.', '2008-02-23 22:54:19.000000', NULL, 0),
